impl<T> Consumer<T> {
    fn dequeue(&mut self) -> (t: T)
        requires
            old(self).wf(),
        ensures
            final(self).wf(),
    {
        loop
            invariant
                self.wf(),
        {
            let queue = &*self.queue;
            let len = queue.buffer.len();
            assert(0 <= self.head && self.head < len);
            let next_head = if self.head + 1 == len {
                0
            } else {
                self.head + 1
            };
            let tracked mut cell_perm: Option<cell::PointsTo<T>> = Option::None;
            let tail =
                atomic_with_ghost!(&queue.tail => load();
                returning tail;
                ghost tail_token => {
                    if self.head as u64 != tail {
                        let tracked (Ghost(_storage), Tracked(perm)) = queue.instance.borrow().consume_start(
                            &tail_token,
                            &mut self.consumer,
                        );
                        cell_perm = Option::Some(perm);
                    }
                }
            );
            if self.head as u64 != tail {
                let tracked mut cell_perm = match cell_perm {
                    Option::Some(cp) => cp,
                    Option::None => {
                        assert(false);
                        proof_from_false()
                    },
                };
                let t = queue.buffer[self.head].take(Tracked(&mut cell_perm));
                atomic_with_ghost!(&queue.head => store(next_head as u64); ghost head_token => {
                    queue.instance.borrow().consume_end(
                        cell_perm,
                        cell_perm,
                        &mut head_token,
                        &mut self.consumer,
                    );
                });
                self.head = next_head;
                return t;
            }
        }
    }
